using System;
using System.Linq;
using Microsoft.EntityFrameworkCore;

namespace EFCoreRawSqlExample
{
    public class Blog
    {
        public int BlogId { get; set; }
        public string Url { get; set; }
    }

    public class BloggingContext : DbContext
    {
        public DbSet<Blog> Blogs { get; set; }

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
        {
            optionsBuilder.UseInMemoryDatabase("BloggingDatabase");
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            using (var context = new BloggingContext())
            {
                // Add a new blog for testing
                context.Blogs.Add(new Blog { Url = "http://example.com" });
                context.SaveChanges();

                // Safe raw SQL query with parameters using FromSqlRaw
                var blogs1 = context.Blogs
                    .FromSqlRaw("SELECT * FROM Blogs WHERE Url = {0}", "http://example.com")
                    .ToList();

                // Safe raw SQL query with interpolated string using FromSqlInterpolated
                string url = "http://example.com";
                var blogs2 = context.Blogs
                    .FromSqlInterpolated($"SELECT * FROM Blogs WHERE Url = {url}")
                    .ToList();

                // Display results
                foreach (var blog in blogs1)
                {
                    Console.WriteLine($"Blog: {blog.Url}");
                }

                // Safe raw SQL command with ExecuteSqlRaw
                context.Database.ExecuteSqlRaw("UPDATE Blogs SET Url = {0} WHERE BlogId = {1}", "http://newurl.com", 1);

                // Safe raw SQL command with ExecuteSqlInterpolated
                int blogId = 1;
                string newUrl = "http://newurl.com";
                context.Database.ExecuteSqlInterpolated($"UPDATE Blogs SET Url = {newUrl} WHERE BlogId = {blogId}");
            }
        }
    }
}
